  var controls=new FlowLayoutPanel{Dock=DockStyle.Top,Height=70};var taskId=new TextBox{Width=280,PlaceholderText="Task ID for pause/resume/cancel"};controls.Controls.Add(taskId);var label=new Label{AutoSize=true,Text="Loading current local state..."};
  using var floating=new Form{Text="MCP Task Panel",Width=500,Height=340,TopMost=true,ShowInTaskbar=false,StartPosition=FormStartPosition.Manual,Location=new Point(30,30)};var floatText=new Label{Dock=DockStyle.Fill,Padding=new Padding(12),Text="Codex is the reasoning engine.\nReady for authorized tasks."};floating.Controls.Add(floatText);var floatingTaskId=new TextBox{Dock=DockStyle.Top,PlaceholderText="Task ID (blank selects the first active task)"};floating.Controls.Add(floatingTaskId);floatingTaskId.TextChanged+=(_,_)=>{if(taskId.Text!=floatingTaskId.Text)taskId.Text=floatingTaskId.Text;};taskId.TextChanged+=(_,_)=>{if(floatingTaskId.Text!=taskId.Text)floatingTaskId.Text=taskId.Text;};var floatingButtons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=85};floating.Controls.Add(floatingButtons);
  async Task<string> Run(string action,string id=""){var start=new ProcessStartInfo(node){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=project};start.ArgumentList.Add(Path.Combine(project,"dist","runtime","control.js"));start.ArgumentList.Add(action);if(id!="")start.ArgumentList.Add(id);using var child=Process.Start(start)!;var output=child.StandardOutput.ReadToEndAsync();var error=child.StandardError.ReadToEndAsync();await child.WaitForExitAsync();if(child.ExitCode!=0)throw new Exception(await error);return await output;}
