  var open=new Button{Text="Open Workspace",AutoSize=true};open.Click+=(_,_)=>Process.Start(new ProcessStartInfo(Path.Combine(project,"workspace")){UseShellExecute=true});controls.Controls.Add(open);
  var panel=new Button{Text="Floating Panel",AutoSize=true};panel.Click+=(_,_)=>{if(floating.Visible)floating.Hide();else floating.Show(form);};controls.Controls.Add(panel);controls.Controls.Add(label);form.Controls.Add(tabs);form.Controls.Add(controls);
  using var timer=new System.Windows.Forms.Timer{Interval=10000};timer.Tick+=async(_,_)=>await Refresh();form.Shown+=async(_,_)=>{timer.Start();await Refresh();};form.FormClosed+=(_,_)=>timer.Stop();Application.Run(form);
 }
}
